{
  "items": [
    {
      "name": "Nat.pow_le_of_le_log",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ {b x y : ℕ}, y ≠ 0 → x ≤ Nat.log b y → b ^ x ≤ y"
    },
    {
      "name": "Nat.le_pow_iff_clog_le",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ {b : ℕ}, 1 < b → ∀ {x y : ℕ}, x ≤ b ^ y ↔ Nat.clog b x ≤ y"
    },
    {
      "name": "Nat.clog_le_iff_le_pow",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ {b : ℕ}, 1 < b → ∀ {x y : ℕ}, Nat.clog b x ≤ y ↔ x ≤ b ^ y"
    },
    {
      "name": "Nat.pow_le_iff_le_log",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ {b : ℕ}, 1 < b → ∀ {x y : ℕ}, y ≠ 0 → (b ^ x ≤ y ↔ x ≤ Nat.log b y)"
    },
    {
      "name": "Nat.lt_pow_of_log_lt",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ {b x y : ℕ}, 1 < b → Nat.log b y < x → y < b ^ x"
    }
  ]
}
